'use strict';
function checkedReceiptLink(value){const raw=String(value||'').trim();if(!raw)return '';let url;try{url=new URL(raw)}catch{throw Error('Вкажіть повне посилання https://…')}if(!['https:','http:'].includes(url.protocol)||url.username||url.password)throw Error('Дозволені посилання http:// або https:// без пароля');return url.href}
function receiptURL(transaction,file){const attachment=file||state.files.filter(f=>f.txId===transaction?.id).sort((a,b)=>Number(b.pinned)-Number(a.pinned))[0];const custom=file?.receiptLink||transaction?.receiptLink||attachment?.receiptLink;if(custom){try{return checkedReceiptLink(custom)}catch{}}const url=new URL('index.html',location.href);url.hash=attachment?'file/'+encodeURIComponent(attachment.id):'receipt/'+encodeURIComponent(transaction?.id||'');return url.href}
const txFormBeforeReceiptURL=txForm;txForm=function(id){txFormBeforeReceiptURL(id);const t=state.transactions.find(t=>t.id===id);$('#fields').insertAdjacentHTML('beforeend',field('Посилання на квитанцію · необов’язково','receiptLink',t?.receiptLink||'','url','maxlength="2000" placeholder="https://…"')+'<p class="form-note">Це посилання відображатиметься в операції та використовуватиметься кнопкою «Поділитися квитанцією». Порожнє поле залишає локальне посилання застосунку.</p>');const save=submit;submit=async f=>{const link=checkedReceiptLink(f.get('receiptLink'));await save(f);const item=id?state.transactions.find(t=>t.id===id):state.transactions.at(-1);if(item)item.receiptLink=link}};
const addFileBeforeReceiptURL=addFile;addFile=function(txId){addFileBeforeReceiptURL(txId);$('#fields').insertAdjacentHTML('beforeend',field('Посилання на квитанцію · необов’язково','receiptLink','','url','maxlength="2000" placeholder="https://…"'));const save=submit;submit=async f=>{const link=checkedReceiptLink(f.get('receiptLink'));await save(f);if(state.files.at(-1))state.files.at(-1).receiptLink=link}};
const editFileBeforeReceiptURL=actions['admin-file'];actions['admin-file']=b=>{editFileBeforeReceiptURL(b);const file=state.files.find(f=>f.id===b.dataset.id);$('#fields').insertAdjacentHTML('beforeend',field('Посилання на квитанцію','receiptLink',file?.receiptLink||'','url','maxlength="2000" placeholder="https://…"'));const save=submit;submit=async f=>{const link=checkedReceiptLink(f.get('receiptLink'));await save(f);const item=state.files.find(f=>f.id===b.dataset.id);if(item)item.receiptLink=link}};
